def isScramble(s1, s2):
    n = len(s1)
    if n != len(s2):
        return False
    memo = {}

    def go(i, j, L):
        key = (i, j, L)
        if key in memo:
            return memo[key]
        a = s1[i:i + L]
        b = s2[j:j + L]
        if a == b:
            res = True
        elif sorted(a) != sorted(b):
            res = False
        else:
            res = False
            for k in range(1, L):
                if go(i, j, k) and go(i + k, j + k, L - k):
                    res = True
                    break
                if go(i, j + L - k, k) and go(i + k, j, L - k):
                    res = True
                    break
        memo[key] = res
        return res

    return go(0, 0, n)
